CREATE TABLE "Match" ("id" UUID PRIMARY KEY, "seed" BIGINT NOT NULL, "squad" TEXT NOT NULL, "private" BOOLEAN NOT NULL, "status" TEXT NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL, "endedAt" TIMESTAMP(3), "score" INTEGER NOT NULL, "wave" INTEGER NOT NULL);
CREATE TABLE "Participant" ("id" UUID PRIMARY KEY, "matchId" UUID NOT NULL REFERENCES "Match"("id") ON DELETE CASCADE, "callsign" TEXT NOT NULL, "kills" INTEGER NOT NULL);
